// SPDX-License-Identifier: Apache-2.0
// Kernel/shared-queue serving with upstream model graphs and GPU-owned metadata.
#include <cuda_runtime.h>
#include <bpf/bpf.h>
#include <sys/mman.h>
#include <sys/syscall.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <cstdio>
#include <cstdlib>
#include <csignal>
#include <vector>
#include "bpfusion_queue.h"
#define CUDA(x) do { cudaError_t e=(x); if(e) { fprintf(stderr,"%s: %s\n",#x,cudaGetErrorString(e)); return (int)e; } } while(0)
#ifdef BF_USER_NETWORK
#include "userspace_tcp.h"
#endif
#ifdef BF_URING_NETWORK
#include "io_uring_tcp.h"
#endif
struct Step { cudaGraphExec_t graph; long long* output; };
struct Inputs {
    int *ids,*lens,*starts,*table,*pages;
    long long *positions,*slots;
    bool* padding;
    unsigned stride,block_size,pages_per_request;
};
struct Request { unsigned id,prompt,gen,k,position,last,phase; };
struct Trace {
    unsigned kind,id,query,batch,gen,bad;
    unsigned long long client_ns;
    unsigned requests[BF_LLM_SLOTS],tokens[BF_LLM_MAX_TOK];
};
struct Control {
    unsigned seen,retired,reclaim,error,launches,device_launch_calls,max_active,batch,query,release_rounds,max_release;
    unsigned selected[BF_LLM_SLOTS];
    Request requests[BF_LLM_SLOTS];
    Trace* trace;
    unsigned trace_capacity,trace_count,trace_overflows;
};
__device__ unsigned queue_load(const unsigned* p) {
    unsigned value;asm volatile("ld.acquire.sys.global.u32 %0, [%1];" : "=r"(value) : "l"(p) : "memory");return value;
}
__device__ unsigned long long queue_load(const unsigned long long* p) {
    unsigned long long value;asm volatile("ld.acquire.sys.global.u64 %0, [%1];" : "=l"(value) : "l"(p) : "memory");return value;
}
__device__ Trace* trace_next(Control* c) {
#ifdef BF_TRACE
    unsigned index=c->trace_count++;
    if(index<c->trace_capacity)return &c->trace[index];
    c->trace_overflows++;
#endif
    return nullptr;
}
__global__ void dispatch(bf_page* p,Step* steps,Inputs in,unsigned vocab,Control* c) {
    if(threadIdx.x || blockIdx.x)return;
    for(;;) {
        if(c->batch) {
            Trace* event=trace_next(c);
            if(event) { event->kind=2;event->query=c->query;event->batch=c->batch; }
            Step* step=&steps[c->query*BF_LLM_SLOTS+c->batch-1];
            for(unsigned row=0;row<c->batch;row++) {
                unsigned i=c->selected[row];Request* r=&c->requests[i];
                unsigned token=(unsigned)step->output[row];
                if(event) { event->requests[row]=r->id;event->tokens[row]=token; }
                bf_llm_slot* slot=&p->llm[i];
                __stcg(&slot->tok_out[r->k],token);__threadfence_system();__stcg(&slot->produced,r->k+1);
                r->last=token;r->k++;
                r->position=c->query ? r->prompt : r->position+1;
                r->phase=r->k==r->gen ? 2 : 1;
            }
            c->batch=0;
        }
        if(queue_load((unsigned long long*)&p->stop_ns))return;
        unsigned release_begin=c->retired,i=c->retired%BF_LLM_SLOTS;
#ifdef BF_PREFIX_RELEASE
        // Model/head work is complete. TX owns each reservation until its
        // final slot access; releasing the FIFO prefix needs no global wait.
        while(c->retired!=c->seen && c->requests[i].phase==2) {
            __threadfence_system();__stcg(&p->llm[i].state,(unsigned)BF_DONE);
            c->requests[i].phase=0;c->retired++;i=c->retired%BF_LLM_SLOTS;
        }
#else
        if(c->reclaim && queue_load(&p->llm[(c->retired-1)%BF_LLM_SLOTS].state)!=BF_DONE)c->reclaim=0;
        if(!c->reclaim && c->retired!=c->seen && c->requests[i].phase==2) {
            __threadfence_system();__stcg(&p->llm[i].state,(unsigned)BF_DONE);
            c->requests[i].phase=0;c->retired++;c->reclaim=1;
        }
#endif
        unsigned released=c->retired-release_begin;
        if(released) {
            c->release_rounds++;if(released>c->max_release)c->max_release=released;
            Trace* event=trace_next(c);
            if(event) {
                event->kind=3;event->batch=released;
                for(unsigned row=0;row<released;row++)event->requests[row]=release_begin+row;
            }
        }
#ifdef BF_IO_COALESCED
        // Advance I/O after result publication and before model admission.
        // This CTA returns while model children execute.
        io_progress(io_state);
#endif
        while(queue_load(&p->llm_head)!=c->seen) {
            i=c->seen%BF_LLM_SLOTS;bf_llm_slot* slot=&p->llm[i];
            if(c->requests[i].phase || queue_load(&slot->state)!=BF_PENDING)break;
            unsigned np=__ldcg(&slot->n_prompt),ng=__ldcg(&slot->n_gen);
            bool bad=!np || np>BF_LLM_MAX_TOK || !ng || ng>BF_LLM_MAX_TOK;
            for(unsigned j=0;j<np && j<BF_LLM_MAX_TOK;j++)if(__ldcg(&slot->tok_in[j])>=vocab)bad=true;
            unsigned short flags=__ldcg(&slot->pad);
            __threadfence_system();
            __stcg(&slot->pad,(unsigned short)((flags&~(BF_LLM_VALIDATING|BF_LLM_REJECTED))|(bad ? BF_LLM_REJECTED : 0)));
            c->requests[i]={c->seen,np,ng,0,0,0,bad ? 2u : 3u};
            Trace* event=trace_next(c);
            if(event) {
                event->kind=1;event->id=c->seen;event->query=np;event->gen=ng;event->bad=bad;
                event->client_ns=queue_load((unsigned long long*)&slot->client_ns);
                for(unsigned j=0;j<np && j<BF_LLM_MAX_TOK;j++)event->tokens[j]=__ldcg(&slot->tok_in[j]);
            }
            c->seen++;
        }
        unsigned query=0;
        for(unsigned id=c->retired;id!=c->seen;id++) {
            Request* r=&c->requests[id%BF_LLM_SLOTS];
            if(r->phase==3) {
#ifdef BF_PAD_PREFILL
                if(r->prompt>query)query=r->prompt;
#else
                query=r->prompt;break;
#endif
            }
        }
        for(unsigned id=c->retired;id!=c->seen;id++) {
            i=id%BF_LLM_SLOTS;Request* r=&c->requests[i];
            if((query && r->phase==3
#ifndef BF_PAD_PREFILL
                && r->prompt==query
#endif
            ) || (!query && r->phase==1))c->selected[c->batch++]=i;
        }
        if(!c->batch)continue;
        unsigned length=query ? query : 1;
        for(unsigned row=0;row<c->batch;row++) {
            i=c->selected[row];Request* r=&c->requests[i];
            in.lens[row]=query ? r->prompt : r->position+1;
            in.starts[row]=row*length;
            for(unsigned column=0;column<in.pages_per_request;column++)
                in.table[row*in.stride+column]=in.pages[i*in.pages_per_request+column];
            for(unsigned j=0;j<length;j++) {
                unsigned index=row*length+j,pad=query ? query-r->prompt : 0;
                bool dummy=j<pad;
                unsigned position=query ? (dummy ? 0 : j-pad) : r->position;
                in.ids[index]=dummy ? 0 : (query ? __ldcg(&p->llm[i].tok_in[j-pad]) : r->last);
                in.positions[index]=position;in.padding[index]=dummy;
                in.slots[index]=dummy ? -1 : (long long)in.pages[i*in.pages_per_request+position/in.block_size]*in.block_size+position%in.block_size;
            }
            r->phase=4;
        }
        in.starts[c->batch]=c->batch*length;c->query=query;
        if(c->batch>c->max_active)c->max_active=c->batch;
        __threadfence();
        cudaError_t e=cudaGraphLaunch(steps[query*BF_LLM_SLOTS+c->batch-1].graph,
#ifdef BF_CHAINED_DISPATCH
            cudaStreamGraphTailLaunch);
#else
            cudaStreamGraphFireAndForget);
#endif
        if(e) { c->error=e;return; }
        c->launches++;c->device_launch_calls++;
#ifndef BF_CHAINED_DISPATCH
        e=cudaGraphLaunch(cudaGetCurrentGraphExec(),cudaStreamGraphTailLaunch);
        if(e)c->error=e;else c->device_launch_calls++;
#endif
        return;
    }
}
extern "C" unsigned max_tokens() { return BF_LLM_MAX_TOK; }
extern "C" unsigned max_requests() { return BF_LLM_SLOTS; }
static volatile sig_atomic_t stopped=0;
static void stop_signal(int) {
    stopped=1;
#ifdef BF_URING_BPF_LOOP
    uring_interrupt();
#endif
}
extern "C" int serve(const unsigned long long* bodies,const unsigned long long* heads,
 const unsigned long long* outputs,const unsigned long long* pointers,unsigned stride,
 unsigned block_size,unsigned pages_per_request,unsigned vocab,unsigned layers,unsigned h,
 unsigned seconds,unsigned trace_requests,const char* trace_path) {
    unsigned size=(BF_LLM_MAX_TOK+1)*BF_LLM_SLOTS;
    std::vector<Step> host(size);std::vector<cudaGraph_t> combined(size);
    Step* steps;CUDA(cudaMalloc(&steps,size*sizeof(Step)));
    Inputs in={};
    in.ids=(int*)pointers[0];in.positions=(long long*)pointers[1];in.lens=(int*)pointers[2];
    in.starts=(int*)pointers[3];in.padding=(bool*)pointers[4];in.slots=(long long*)pointers[5];
    in.table=(int*)pointers[6];in.pages=(int*)pointers[7];in.stride=stride;in.block_size=block_size;in.pages_per_request=pages_per_request;
    Control initial={};
#ifdef BF_TRACE
    Trace* trace=nullptr;
    if(!trace_requests || !trace_path || !*trace_path) { fprintf(stderr,"traced candidate requires bounded workload and output path\n");return 1; }
    initial.trace_capacity=trace_requests*(BF_LLM_MAX_TOK+2);
    CUDA(cudaMalloc(&trace,initial.trace_capacity*sizeof(Trace)));initial.trace=trace;
#endif
    Control* control;CUDA(cudaMalloc(&control,sizeof(Control)));CUDA(cudaMemcpy(control,&initial,sizeof(initial),cudaMemcpyHostToDevice));
#ifdef BF_USER_NETWORK
    bf_page* page=(bf_page*)mmap(nullptr,BF_PAGE_MMAP_BYTES,PROT_READ|PROT_WRITE,MAP_SHARED|MAP_ANONYMOUS,-1,0);
#else
    int fd=bpf_obj_get("/sys/fs/bpf/bpfusion_ctl");if(fd<0) { perror("bpf_obj_get");return 1; }
    bf_page* page=(bf_page*)mmap(nullptr,BF_PAGE_MMAP_BYTES,PROT_READ|PROT_WRITE,MAP_SHARED,fd,0);
#endif
    if(page==MAP_FAILED) { perror("mmap");return 1; }
    CUDA(cudaHostRegister(page,BF_PAGE_MMAP_BYTES,cudaHostRegisterMapped));
    bf_page* device;CUDA(cudaHostGetDevicePointer((void**)&device,page,0));
    int listener=socket(AF_INET,SOCK_STREAM,0),yes=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof(yes));
    sockaddr_in addr={};addr.sin_family=AF_INET;addr.sin_port=htons(BF_LLM_TCP_PORT);
    const char* bind_addr=getenv("BF_BIND");
    if(inet_pton(AF_INET,bind_addr ? bind_addr : "127.0.0.1",&addr.sin_addr)!=1) { fprintf(stderr,"BF_BIND must be an IPv4 address\n");return 1; }
    if(bind(listener,(sockaddr*)&addr,sizeof(addr)) || listen(listener,SOMAXCONN)) { perror("listen");return 1; }
    __atomic_store_n(&page->stop_ns,0,__ATOMIC_RELEASE);
    void* args[]={&device,&steps,&in,&vocab,&control};
    cudaKernelNodeParams params={};params.func=(void*)dispatch;params.gridDim=dim3(1);params.blockDim=dim3(32);params.kernelParams=args;
    for(unsigned q=1;q<=BF_LLM_MAX_TOK;q++)for(unsigned b=1;b<=BF_LLM_SLOTS;b++) {
        unsigned index=q*BF_LLM_SLOTS+b-1;cudaGraphNode_t body,head;
        CUDA(cudaGraphCreate(&combined[index],0));
        CUDA(cudaGraphAddChildGraphNode(&body,combined[index],nullptr,0,(cudaGraph_t)bodies[index]));
        CUDA(cudaGraphAddChildGraphNode(&head,combined[index],&body,1,(cudaGraph_t)heads[index]));
#ifdef BF_CHAINED_DISPATCH
        // All body/head writes precede dispatch. Tail launch finishes this
        // environment before the next step, including self-relaunch.
        cudaGraphNode_t next;
        CUDA(cudaGraphAddKernelNode(&next,combined[index],&head,1,&params));
#endif
        CUDA(cudaGraphInstantiateWithFlags(&host[index].graph,combined[index],cudaGraphInstantiateFlagDeviceLaunch));
        CUDA(cudaGraphUpload(host[index].graph,0));host[index].output=(long long*)outputs[index];
    }
    for(unsigned b=0;b<BF_LLM_SLOTS;b++)host[b]=host[BF_LLM_SLOTS+b];
    CUDA(cudaMemcpy(steps,host.data(),size*sizeof(Step),cudaMemcpyHostToDevice));
    cudaGraph_t parent_graph;cudaGraphNode_t node;cudaGraphExec_t parent;
    CUDA(cudaGraphCreate(&parent_graph,0));CUDA(cudaGraphAddKernelNode(&node,parent_graph,nullptr,0,&params));
    CUDA(cudaGraphInstantiateWithFlags(&parent,parent_graph,cudaGraphInstantiateFlagDeviceLaunch));CUDA(cudaGraphUpload(parent,0));CUDA(cudaDeviceSynchronize());
#ifdef BF_URING_NETWORK
    UringNetwork network{};
    if(uring_start(page,device,listener,&network))return 1;
    close(fd);
#elif !defined(BF_USER_NETWORK)
    int module=open("module/bfusion_tx.ko",O_RDONLY|O_CLOEXEC);if(module<0) { perror("module open");return 1; }
    char module_params[80];snprintf(module_params,sizeof(module_params),"map_fd=%d listen_fd=%d",fd,listener);
    if(syscall(SYS_finit_module,module,module_params,0)) { perror("finit_module");return 1; }
    close(module);close(fd);
#endif
    signal(SIGTERM,stop_signal);signal(SIGINT,stop_signal);
    cudaError_t launched=cudaGraphLaunch(parent,0);
    if(launched==cudaSuccess) {
        printf("resident vLLM ready: %u layers h=%u vocab=%u; tensor batches1..%u, GPU prefill/decode\n",layers,h,vocab,BF_LLM_SLOTS);fflush(stdout);
#ifdef BF_USER_NETWORK
        launched=user_network(page,listener,seconds,&stopped) ? cudaErrorUnknown : cudaSuccess;
#elif defined(BF_URING_BPF_LOOP)
        launched=uring_wait(&network,seconds,&stopped) ? cudaErrorUnknown : cudaSuccess;
#else
        while(seconds-- && !stopped)sleep(1);
#endif
    }
    __atomic_store_n(&page->stop_ns,1,__ATOMIC_RELEASE);
#ifdef BF_URING_NETWORK
    cudaError_t finished=cudaStreamSynchronize(0);CUDA(finished);
    uring_quiesce(&network);
#ifdef BF_URING_BPF_LOOP
    if(uring_drain(&network))return 1;
#endif
    finished=cudaDeviceSynchronize();
    if(uring_finish(&network))return 1;
#else
cudaError_t finished=cudaDeviceSynchronize();
#ifndef BF_USER_NETWORK
    if(syscall(SYS_delete_module,"bfusion_tx",0)) { perror("delete_module");return 1; }
#endif
#endif
    close(listener);CUDA(launched);CUDA(finished);
    Control result;CUDA(cudaMemcpy(&result,control,sizeof(result),cudaMemcpyDeviceToHost));
#ifdef BF_TRACE
    unsigned count=result.trace_count<result.trace_capacity ? result.trace_count : result.trace_capacity;
    std::vector<Trace> records(count);CUDA(cudaMemcpy(records.data(),trace,count*sizeof(Trace),cudaMemcpyDeviceToHost));
    FILE* file=fopen(trace_path,"w");if(!file) { perror("trace output");return 1; }
    for(const auto& r:records) {
        if(r.kind==1) {
            fprintf(file,"{\"event\":\"admission\",\"id\":%u,\"query\":%u,\"gen\":%u,\"bad\":%u,\"client_ns\":%llu,\"input_ids\":[",r.id,r.query,r.gen,r.bad,r.client_ns);
            for(unsigned j=0;j<r.query && j<BF_LLM_MAX_TOK;j++)fprintf(file,"%s%u",j ? "," : "",r.tokens[j]);
        }else if(r.kind==3) {
            fprintf(file,"{\"event\":\"release\",\"batch\":%u,\"request_ids\":[",r.batch);
            for(unsigned j=0;j<r.batch;j++)fprintf(file,"%s%u",j ? "," : "",r.requests[j]);
        }else {
            fprintf(file,"{\"event\":\"compute\",\"query\":%u,\"batch\":%u,\"request_ids\":[",r.query,r.batch);
            for(unsigned j=0;j<r.batch;j++)fprintf(file,"%s%u",j ? "," : "",r.requests[j]);
            fprintf(file,"],\"tokens\":[");
            for(unsigned j=0;j<r.batch;j++)fprintf(file,"%s%u",j ? "," : "",r.tokens[j]);
        }
        fprintf(file,"]}\n");
    }
    fprintf(file,"{\"event\":\"terminal\",\"records\":%u,\"overflows\":%u}\n",result.trace_count,result.trace_overflows);
    if(fclose(file)) { perror("trace close");return 1; }
    CUDA(cudaFree(trace));
#endif
    CUDA(cudaHostUnregister(page));munmap(page,BF_PAGE_MMAP_BYTES);
    CUDA(cudaGraphExecDestroy(parent));CUDA(cudaGraphDestroy(parent_graph));CUDA(cudaFree(steps));CUDA(cudaFree(control));
    for(unsigned index=BF_LLM_SLOTS;index<size;index++) { CUDA(cudaGraphExecDestroy(host[index].graph));CUDA(cudaGraphDestroy(combined[index])); }
    printf("resident vLLM stopped: launches=1 device_graph_launches=%u graph_error=%u max_active=%u admitted=%u retired=%u trace_overflows=%u release_rounds=%u max_release=%u device_launch_calls=%u\n",result.launches,result.error,result.max_active,result.seen,result.retired,result.trace_overflows,result.release_rounds,result.max_release,result.device_launch_calls);fflush(stdout);
    return result.error || result.trace_overflows;
}

amk_builder_source:
// SPDX-License-Identifier: Apache-2.0
// Bootstrap glue only. All model instructions remain in upstream AMK's cubin.
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <cstddef>
#include "amk_persist.cuh"
struct Model { CUmodule module{}; CUfunction function{}; };
static const char* last_stage="";
extern "C" const char* amk_stage() { return last_stage; }
extern "C" size_t amk_args_size() { return sizeof(amk_persist_launch_args); }
__global__ void prepare(cudaGraphDeviceNode_t node,const long long* input,unsigned index,int* error) {
    if(threadIdx.x)return;
    int token=(int)input[index];
    cudaError_t e=cudaGraphKernelNodeSetParam(node,offsetof(amk_persist_program,first_token),token);
    if(e)atomicCAS(error,0,(int)e);
}
__global__ void selected(const int* token,long long* output) { if(!threadIdx.x)*output=*token; }
extern "C" int amk_open(const char* cubin,Model** output) {
    Model* m=new Model;CUresult e=cuModuleLoad(&m->module,cubin);
    if(!e)e=cuModuleGetFunction(&m->function,m->module,"amk_megakernel_persist");
    if(e){if(m->module)cuModuleUnload(m->module);delete m;return e;}
    *output=m;return 0;
}
extern "C" void amk_close(Model* m) { cuModuleUnload(m->module);delete m; }
extern "C" int amk_graph_create(Model* m,const amk_persist_launch_args* a,
    const long long* input,unsigned start,unsigned count,long long* output,int* error,CUgraph* result) {
    CUgraph graph{};CUresult e;
#define C(call) do {last_stage=#call;e=(call);if(e){if(graph)cuGraphDestroy(graph);return (int)e;}} while(0)
#define R(call) do {last_stage=#call;cudaError_t x=(call);if(x){if(graph)cuGraphDestroy(graph);return 10000+(int)x;}} while(0)
    cudaFunction_t prep{},head{};R(cudaGetFuncBySymbol(&prep,(const void*)prepare));
    R(cudaGetFuncBySymbol(&head,(const void*)selected));
    C(cuGraphCreate(&graph,0));
    amk_persist_program pp{};
    pp.base.buffers=(const amk_buffer_t*)a->buffers_ptr; pp.base.n_buffers=a->n_buffers;
    pp.base.counters=(amk_counter_t*)a->counters_ptr; pp.base.n_counters=a->n_counters;
    pp.base.instructions=(const amk_instruction_t*)a->instructions_ptr; pp.base.n_instructions=a->n_instructions;
    pp.base.sm_queue_flat=(const int32_t*)a->sm_queue_flat_ptr;
    pp.base.sm_queue_off=(const int32_t*)a->sm_queue_off_ptr; pp.base.sm_queue_len=(const int32_t*)a->sm_queue_len_ptr;
    pp.base.num_sms=a->num_sms; pp.base.scratch=(unsigned char*)a->scratch_ptr;
    pp.base.scratch_bytes=a->scratch_bytes; pp.base.abort_flag=(int32_t*)a->abort_flag_ptr;
    pp.K=a->K; pp.base_pos=a->base_pos; pp.pos_cell=(int32_t*)a->pos_cell_ptr;
    pp.token_cell=(int32_t*)a->token_cell_ptr;
    pp.logits=(const amk_buffer_t*)a->buffers_table_ptr+a->logits_buf_idx;
    pp.generated=(int32_t*)a->generated_ptr; pp.first_token=a->first_token;
    pp.K=1;
    CUgraphNode previous{};
    for(unsigned position=start;position<start+count;position++) {
        pp.base_pos=position;pp.first_token=0;
        void* model_args[]={&pp};
        CUDA_KERNEL_NODE_PARAMS model{};
        model.func=m->function;model.gridDimX=a->grid_dim;model.gridDimY=model.gridDimZ=1;
        model.blockDimX=a->threads_per_block;model.blockDimY=model.blockDimZ=1;
        model.sharedMemBytes=a->dyn_smem_bytes;model.kernelParams=model_args;
        CUgraphNode model_node{};C(cuGraphAddKernelNode(&model_node,graph,nullptr,0,&model));
        CUkernelNodeAttrValue attribute{};attribute.cooperative=1;
        C(cuGraphKernelNodeSetAttribute(model_node,CU_KERNEL_NODE_ATTRIBUTE_COOPERATIVE,&attribute));
        attribute={};attribute.deviceUpdatableKernelNode.deviceUpdatable=1;
        C(cuGraphKernelNodeSetAttribute(model_node,CU_KERNEL_NODE_ATTRIBUTE_DEVICE_UPDATABLE_KERNEL_NODE,&attribute));
        C(cuGraphKernelNodeGetAttribute(model_node,CU_KERNEL_NODE_ATTRIBUTE_DEVICE_UPDATABLE_KERNEL_NODE,&attribute));
        cudaGraphDeviceNode_t node=(cudaGraphDeviceNode_t)attribute.deviceUpdatableKernelNode.devNode;
        unsigned input_index=count==1?0:position;
        void* prep_args[]={&node,&input,&input_index,&error};
        CUDA_KERNEL_NODE_PARAMS params{};params.func=(CUfunction)prep;
        params.gridDimX=params.gridDimY=params.gridDimZ=1;params.blockDimX=params.blockDimY=params.blockDimZ=1;
        params.kernelParams=prep_args;
        CUgraphNode prep_node{};C(cuGraphAddKernelNode(&prep_node,graph,previous?&previous:nullptr,previous?1:0,&params));
        C(cuGraphAddDependencies(graph,&prep_node,&model_node,nullptr,1));
        previous=model_node;
    }
    int* token=(int*)a->generated_ptr;void* head_args[]={&token,&output};
    CUDA_KERNEL_NODE_PARAMS params{};params.func=(CUfunction)head;
    params.gridDimX=params.gridDimY=params.gridDimZ=1;params.blockDimX=params.blockDimY=params.blockDimZ=1;params.kernelParams=head_args;
    CUgraphNode final{};C(cuGraphAddKernelNode(&final,graph,&previous,1,&params));
    *result=graph;last_stage="graph_created";return 0;
#undef C
#undef R
}
extern "C" int amk_graph_destroy(CUgraph graph) { return cuGraphDestroy(graph); }

amk_dispatcher_source:
// SPDX-License-Identifier: Apache-2.0
// GPU-tail graph dispatch: host work is model/graph bootstrap and shutdown only.
#include <cuda_runtime.h>
#include <bpf/bpf.h>
#include <sys/mman.h>
#include <sys/syscall.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <cstdlib>
#include <unistd.h>
#include <cstdio>
#include <csignal>
#include <vector>
#include "bpfusion_queue.h"
#define CUDA(x) do { cudaError_t e=(x); if(e!=cudaSuccess) { fprintf(stderr,"%s: %s\n",#x,cudaGetErrorString(e)); return (int)e; } } while(0)
#ifdef BF_USER_NETWORK
#include "userspace_tcp.h"
#endif
#ifdef BF_URING_NETWORK
#include "io_uring_tcp.h"
#endif
struct Step { cudaGraphExec_t graph; long long *output; };
struct Request { unsigned k,prompt,gen,step,phase; };
struct Control { unsigned seen,retired,reclaim,error,launches,max_active; Request requests[BF_LLM_SLOTS]; };

// System-scope acquire protects host publication and forbids polling-load
// elimination; a cache modifier alone does not give synchronization semantics.
__device__ unsigned queue_load(const unsigned *p) {
    unsigned value;asm volatile("ld.acquire.sys.global.u32 %0, [%1];" : "=r"(value) : "l"(p) : "memory");return value;
}
__device__ unsigned long long queue_load(const unsigned long long *p) {
    unsigned long long value;asm volatile("ld.acquire.sys.global.u64 %0, [%1];" : "=l"(value) : "l"(p) : "memory");return value;
}

__global__ void dispatch(bf_page *p,Step *steps,long long **inputs,unsigned count,unsigned vocab,Control *c,bool once) {
    if(threadIdx.x || blockIdx.x) return;
    while(!queue_load((unsigned long long *)&p->stop_ns)) {
        // A parent tail resumes only after all private child graphs finish.
        // phase1 awaits sampling; phase3 awaits launch, including after a
        // host-control return that publishes another request's DONE.
        for(unsigned i=0;i<BF_LLM_SLOTS;i++) {
            Request *r=&c->requests[i];
            if(r->phase!=1) continue;
            unsigned bank=i;
            unsigned token=(unsigned)*steps[bank*count+r->step].output;
            bf_llm_slot *slot=&p->llm[i];
            __stcg(&slot->tok_out[r->k],token);__threadfence_system();__stcg(&slot->produced,r->k+1);
            if(++r->k==r->gen) r->phase=2;
            else { inputs[bank][0]=token;r->step=BF_LLM_MAX_TOK+r->prompt+r->k-1;r->phase=3; }
        }
        // The head-indexed ring must reclaim in admission order. Hold final
        // tokens until the previous DONE was reclaimed by kernel TX. A reused
        // WRITING/PENDING slot also proves that its old ownership was released.
        if(c->reclaim && queue_load(&p->llm[(c->retired-1)%BF_LLM_SLOTS].state)!=BF_DONE) c->reclaim=0;
        unsigned idx=c->retired%BF_LLM_SLOTS;
        if(!c->reclaim && c->retired!=c->seen && c->requests[idx].phase==2) {
            __threadfence_system();__stcg(&p->llm[idx].state,(unsigned)BF_DONE);
            c->requests[idx].phase=0;c->retired++;c->reclaim=1;
            if(once) return;
        }
        // Admission remains sequential; computation uses each physical slot's
        // private KV/input/output bank. No producer or page ABI change.
#ifdef BF_IO_COALESCED
        // Advance I/O after result publication and before model admission.
        // This CTA returns while model children execute.
        io_progress(io_state);
#endif
        while(queue_load(&p->llm_head)!=c->seen) {
            idx=c->seen%BF_LLM_SLOTS;
            bf_llm_slot *slot=&p->llm[idx];
            if(c->requests[idx].phase || queue_load(&slot->state)!=BF_PENDING) break;
            unsigned bank=idx;
            unsigned np=__ldcg(&slot->n_prompt),ng=__ldcg(&slot->n_gen);
            bool bad=!np || np>BF_LLM_MAX_TOK || !ng || ng>BF_LLM_MAX_TOK;
            for(unsigned j=0;j<np && j<BF_LLM_MAX_TOK;j++) {
                unsigned token=__ldcg(&slot->tok_in[j]);
                if(token>=vocab) bad=true;
                inputs[bank][j]=token;
            }
            unsigned short flags=__ldcg(&slot->pad);
            __threadfence_system();
            __stcg(&slot->pad,(unsigned short)((flags&~BF_LLM_VALIDATING)|(bad ? BF_LLM_REJECTED : 0)));
            c->requests[idx]={0,np,ng,np,bad ? 2u : 3u};c->seen++;
        }
        unsigned active=0;
        for(unsigned i=0;i<BF_LLM_SLOTS;i++) {
            Request *r=&c->requests[i];
            if(r->phase!=3) continue;
            unsigned bank=i;
            cudaError_t e=cudaGraphLaunch(steps[bank*count+r->step].graph,cudaStreamGraphFireAndForget);
            if(e!=cudaSuccess) { c->error=e;return; }
            r->phase=1;c->launches++;active++;
        }
        if(active) {
            if(active>c->max_active) c->max_active=active;
            cudaError_t e=cudaGraphLaunch(cudaGetCurrentGraphExec(),cudaStreamGraphTailLaunch);
            if(e!=cudaSuccess) c->error=e;
            return;
        }
        // Idle, rejection and TX reclamation waits stay on the GPU.
    }
}
extern "C" unsigned max_tokens() { return BF_LLM_MAX_TOK; }
extern "C" unsigned max_requests() { return BF_LLM_SLOTS; }
static volatile sig_atomic_t stopped=0;
static void stop_signal(int) {
    stopped=1;
#ifdef BF_URING_BPF_LOOP
    uring_interrupt();
#endif
}
extern "C" int serve(const unsigned long long *graphs,const unsigned long long *outputs,unsigned count,const unsigned long long *input_ptrs,unsigned vocab,unsigned layers,unsigned h,unsigned seconds) {
    unsigned banks=max_requests(),size=count*banks;
    std::vector<Step> host(size);
    for(unsigned i=0;i<size;i++) {
        if(i%count==0) continue;
        CUDA(cudaGraphInstantiate(&host[i].graph,(cudaGraph_t)graphs[i],cudaGraphInstantiateFlagDeviceLaunch));
        CUDA(cudaGraphUpload(host[i].graph,0));host[i].output=(long long *)outputs[i];
    }
    Step *steps;CUDA(cudaMalloc(&steps,size*sizeof(Step)));CUDA(cudaMemcpy(steps,host.data(),size*sizeof(Step),cudaMemcpyHostToDevice));
    Control *control;CUDA(cudaMalloc(&control,sizeof(Control)));CUDA(cudaMemset(control,0,sizeof(Control)));
#ifdef BF_USER_NETWORK
    bf_page *page=(bf_page *)mmap(nullptr,BF_PAGE_MMAP_BYTES,PROT_READ|PROT_WRITE,MAP_SHARED|MAP_ANONYMOUS,-1,0);
#else
    int fd=bpf_obj_get("/sys/fs/bpf/bpfusion_ctl");if(fd<0) { perror("bpf_obj_get");return 1; }
    bf_page *page=(bf_page *)mmap(nullptr,BF_PAGE_MMAP_BYTES,PROT_READ|PROT_WRITE,MAP_SHARED,fd,0);
#endif
    if(page==MAP_FAILED) { perror("mmap");return 1; }
    CUDA(cudaHostRegister(page,BF_PAGE_MMAP_BYTES,cudaHostRegisterMapped));
    bf_page *device;CUDA(cudaHostGetDevicePointer((void **)&device,page,0));
    int listener=socket(AF_INET,SOCK_STREAM,0),yes=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof(yes));
    sockaddr_in addr={};addr.sin_family=AF_INET;addr.sin_port=htons(BF_LLM_TCP_PORT);
    const char *bind_addr=getenv("BF_BIND");
    if(inet_pton(AF_INET,bind_addr ? bind_addr : "127.0.0.1",&addr.sin_addr)!=1) {
        fprintf(stderr,"BF_BIND must be an IPv4 address\n");return 1;
    }
    if(bind(listener,(sockaddr *)&addr,sizeof(addr)) || listen(listener,SOMAXCONN)) { perror("listen");return 1; }
    __atomic_store_n(&page->stop_ns,0,__ATOMIC_RELEASE);
    long long **inputs;CUDA(cudaMalloc(&inputs,banks*sizeof(long long *)));
    CUDA(cudaMemcpy(inputs,input_ptrs,banks*sizeof(long long *),cudaMemcpyHostToDevice));
#ifdef BF_HOST_LAUNCH
    bool once=true;const char *mode="host-launch";
#else
    bool once=false;const char *mode="resident";
#endif
    void *args[]={&device,&steps,&inputs,&count,&vocab,&control,&once};
    cudaKernelNodeParams params={};params.func=(void *)dispatch;params.gridDim=dim3(1);params.blockDim=dim3(32);params.kernelParams=args;
    cudaGraph_t graph;CUDA(cudaGraphCreate(&graph,0));cudaGraphNode_t node;CUDA(cudaGraphAddKernelNode(&node,graph,nullptr,0,&params));
    cudaGraphExec_t parent;CUDA(cudaGraphInstantiate(&parent,graph,cudaGraphInstantiateFlagDeviceLaunch));CUDA(cudaGraphUpload(parent,0));CUDA(cudaDeviceSynchronize());
#ifdef BF_URING_NETWORK
    UringNetwork network{};
    if(uring_start(page,device,listener,&network))return 1;
    close(fd);
#elif !defined(BF_USER_NETWORK)
    int module=open("module/bfusion_tx.ko",O_RDONLY|O_CLOEXEC);if(module<0) { perror("module open");return 1; }
    char params_module[80];snprintf(params_module,sizeof(params_module),"map_fd=%d listen_fd=%d",fd,listener);
    if(syscall(SYS_finit_module,module,params_module,0)) { perror("finit_module");return 1; }
    close(module);close(fd);
#endif
    signal(SIGTERM,stop_signal);signal(SIGINT,stop_signal);
#ifdef BF_USER_NETWORK
    printf("network=userspace epoll; same resident GPU graph dispatch\n");fflush(stdout);
#endif
    cudaError_t launched=cudaSuccess;unsigned launches=0;
    if(!once) { launched=cudaGraphLaunch(parent,0);launches++; }
    if(launched==cudaSuccess) {
        printf("resident Qwen ready: %u layers h=%u vocab=%u; device-tail graphs, dispatch=%s\n",layers,h,vocab,mode);fflush(stdout);
#ifdef BF_USER_NETWORK
        launched=user_network(page,listener,seconds,&stopped) ? cudaErrorUnknown : cudaSuccess;
#elif defined(BF_URING_BPF_LOOP)
        launched=uring_wait(&network,seconds,&stopped) ? cudaErrorUnknown : cudaSuccess;
#else
        if(once) {
            signal(SIGALRM,stop_signal);alarm(seconds);unsigned retired=0;
            while(!stopped) {
                if(__atomic_load_n(&page->llm_head,__ATOMIC_ACQUIRE)==retired ||
                   __atomic_load_n(&page->llm[retired%BF_LLM_SLOTS].state,__ATOMIC_ACQUIRE)!=BF_PENDING) continue;
                launched=cudaGraphLaunch(parent,0);launches++;
                if(launched!=cudaSuccess) break;
                launched=cudaDeviceSynchronize();if(launched!=cudaSuccess) break;
                retired++;
            }
            alarm(0);
        } else while(seconds-- && !stopped) sleep(1);
#endif
    }
    __atomic_store_n(&page->stop_ns,1,__ATOMIC_RELEASE);
#ifdef BF_URING_NETWORK
    cudaError_t finished=cudaStreamSynchronize(0);CUDA(finished);
    uring_quiesce(&network);
#ifdef BF_URING_BPF_LOOP
    if(uring_drain(&network))return 1;
#endif
    finished=cudaDeviceSynchronize();
    if(uring_finish(&network))return 1;
#else
    cudaError_t finished=cudaDeviceSynchronize();
#ifndef BF_USER_NETWORK
    if(syscall(SYS_delete_module,"bfusion_tx",0)) { perror("delete_module");return 1; }
#endif
#endif
    close(listener);CUDA(launched);CUDA(finished);
    Control result;CUDA(cudaMemcpy(&result,control,sizeof(result),cudaMemcpyDeviceToHost));
    CUDA(cudaHostUnregister(page));munmap(page,BF_PAGE_MMAP_BYTES);
    CUDA(cudaGraphExecDestroy(parent));CUDA(cudaGraphDestroy(graph));CUDA(cudaFree(steps));CUDA(cudaFree(inputs));CUDA(cudaFree(control));
    for(unsigned i=0;i<size;i++) if(i%count) CUDA(cudaGraphExecDestroy(host[i].graph));
    printf("resident Qwen stopped: dispatch=%s launches=%u device_graph_launches=%u graph_error=%u banks=%u max_active=%u\n",mode,launches,result.launches,result.error,banks,result.max_active);fflush(stdout);
    return result.error;
}

