            unsigned first=r.sent>r.header?(r.sent-r.header)/4:0;
#endif
            for(unsigned j=first;j<produced;++j) {
                unsigned token=io_load(&slot->tok_out[j]);
                for(unsigned byte=0;byte<4;++byte)tx[r.header+j*4+byte]=(token>>(byte*8))&255;
