#define CUDA(x) do { cudaError_t e=(x); if(e!=cudaSuccess) { fprintf(stderr,"%s: %s\n",#x,cudaGetErrorString(e)); return (int)e; } } while(0)
#ifdef BF_USER_NETWORK
#include "userspace_tcp.h"
#endif
